import{_ as n,C as o,c as r,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"CRM settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/configuration/settings.md","filePath":"master/sales/crm/configuration/settings.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/configuration/settings.md"};function g(d,e,h,u,c,m){const s=o("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="crm-settings" tabindex="-1">CRM settings <a class="header-anchor" href="#crm-settings" aria-label="Permalink to &quot;CRM settings&quot;">​</a></h1><p>CRM settings are the switches that decide which features your CRM shows. Some switches add a menu or extra fields. Others change how leads are handed to your team. Set them once, before your team starts to work.</p><blockquote><p><strong>In simple words:</strong> Settings turn parts of the CRM on or off, and each switch reveals the screens that belong to it.</p></blockquote><p>Open <code>CRM → Settings → Manage CRM</code>. The settings area has three pages: <strong>Manage CRM</strong>, <strong>Manage Lead Scoring</strong> and <strong>Manage Lead Generation</strong>. This page covers <strong>Manage CRM</strong>.</p><h2 id="the-manage-crm-page" tabindex="-1">The Manage CRM page <a class="header-anchor" href="#the-manage-crm-page" aria-label="Permalink to &quot;The Manage CRM page&quot;">​</a></h2>',5)),a(s,{src:"/images1/crm/settings-manage-crm.png",alt:"Manage CRM settings page with the four switches and the Save changes button"}),e[1]||(e[1]=t('<p>The page has four switches. Turn a switch on or off, then click <strong>Save changes</strong>.</p><ul><li><strong><em>Lead Qualification:</em></strong> Adds a qualification step before an opportunity exists. Helper text: add a qualification step before the creation of an opportunity.</li><li><strong><em>Recurring Revenue Plans:</em></strong> Lets you define recurring plans and revenues on opportunities.</li><li><strong><em>Salespeople in Multiple Teams:</em></strong> Lets one salesperson be a member of more than one sales team.</li><li><strong><em>Automatic Lead Assignment:</em></strong> Periodically assigns leads by rules. All sales teams use it by default unless a team says otherwise.</li></ul><h3 id="what-each-switch-reveals" tabindex="-1">What each switch reveals <a class="header-anchor" href="#what-each-switch-reveals" aria-label="Permalink to &quot;What each switch reveals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Switch</th><th>Off</th><th>On</th></tr></thead><tbody><tr><td><strong>Lead Qualification</strong></td><td>The <strong>Leads</strong> menu is hidden. New records start as opportunities.</td><td>The <strong>Leads</strong> menu shows. Records start as leads and you convert them. The lead type choice also appears on lead generation rules.</td></tr><tr><td><strong>Recurring Revenue Plans</strong></td><td>The <strong>Recurring Plans</strong> menu and the recurring fields are hidden.</td><td><strong>Recurring Plans</strong> shows under <code>CRM → Configuration → Members</code>. Opportunities get <strong>Recurring Revenue</strong> and <strong>Recurring Plan</strong>.</td></tr><tr><td><strong>Salespeople in Multiple Teams</strong></td><td>A salesperson belongs to one team.</td><td>A salesperson can be added to several teams.</td></tr><tr><td><strong>Automatic Lead Assignment</strong></td><td>Leads are assigned by hand.</td><td>The <strong>Running</strong> choice shows, the <strong>Assign now</strong> button shows, and teams get assignment settings.</td></tr></tbody></table><p><strong>Example:</strong> You want a qualification step. Turn on <strong>Lead Qualification</strong> and click <strong>Save changes</strong>. The <strong>Leads</strong> menu appears next to <strong>Sales</strong>.</p><h2 id="set-up-automatic-lead-assignment" tabindex="-1">Set up automatic lead assignment <a class="header-anchor" href="#set-up-automatic-lead-assignment" aria-label="Permalink to &quot;Set up automatic lead assignment&quot;">​</a></h2><ol><li><p>Turn on <strong>Automatic Lead Assignment</strong>.</p></li><li><p>In <strong>Running</strong>, choose how the assignment runs. This field is required.</p><ul><li><strong><em>Manually:</em></strong> Leads are assigned only when you click <strong>Assign now</strong>.</li><li><strong><em>Repeatedly:</em></strong> Leads are assigned on a schedule.</li></ul></li><li><p>For <strong>Repeatedly</strong>, fill in two more fields.</p><ul><li><strong><em>Repeat every:</em></strong> A whole number, at least 1. Required.</li><li><strong><em>Unit:</em></strong> Choose <strong>Minutes</strong>, <strong>Hours</strong>, <strong>Days</strong> or <strong>Weeks</strong>. Required.</li></ul></li><li><p>Click <strong>Save changes</strong>.</p></li></ol>',7)),a(s,{src:"/images1/crm/settings-auto-assignment-running.png",alt:"Manage CRM settings with Automatic Lead Assignment on, Running set to Repeatedly, Repeat every 1 and Unit Days"}),e[2]||(e[2]=t('<p><strong>Example:</strong> Choose <strong>Repeatedly</strong>, enter 1 and choose <strong>Days</strong>. Aureus assigns new leads every day.</p><h3 id="assign-now" tabindex="-1">Assign now <a class="header-anchor" href="#assign-now" aria-label="Permalink to &quot;Assign now&quot;">​</a></h3><p><strong>Assign now</strong> is a button in the page header. It shows only while <strong>Automatic Lead Assignment</strong> is on.</p><ol><li>Click <strong>Assign now</strong>.</li><li>Read the message: it assigns unassigned leads to sales teams and salespeople now, using the assignment rules.</li><li>Confirm.</li></ol><p>A notice then reports the result, for example: Assigned 3 lead(s) to sales teams and 2 to salespeople.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Assignment follows the rules you set on each sales team. See <a href="./../pipeline/manage-sales-teams.html">Manage sales teams</a>.</p></div><h2 id="other-settings-pages" tabindex="-1">Other settings pages <a class="header-anchor" href="#other-settings-pages" aria-label="Permalink to &quot;Other settings pages&quot;">​</a></h2><p>Use the page links at the top of the settings area.</p><ul><li><strong>Manage Lead Scoring:</strong> Sets how win probability is calculated. See <a href="./../assign-and-track/lead-scoring.html">Lead scoring</a>.</li><li><strong>Manage Lead Generation:</strong> Turns on leads from website visits and opens the rules. See <a href="./../acquire-leads/lead-generation.html">Lead generation</a>.</li></ul><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>Settings are company wide. Every user sees the same menus after you save.</li><li>Turning <strong>Lead Qualification</strong> off does not delete leads. It hides the menu and changes how new records start.</li><li>Turning <strong>Recurring Revenue Plans</strong> off hides the fields. Values already saved on opportunities stay.</li><li>The scheduled assignment runs on the interval you saved. <strong>Assign now</strong> runs the same job at once.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Check with your team before you turn <strong>Lead Qualification</strong> off. Staff lose the menu where they work on leads.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">CRM configuration</a></li><li><a href="./recurring-plans.html">Recurring plans</a></li><li><a href="./../acquire-leads/create-lead.html">Create a lead</a></li><li><a href="./../pipeline/manage-sales-teams.html">Manage sales teams</a></li></ul>',14))])}const w=n(l,[["render",g]]);export{f as __pageData,w as default};
